// Отдельные примечания-источники для нефакторных врезок под описанием зоны.
const ZONE_EXTRA_SOURCES = {
  crussia:['bryansk_1918']
};

function evidenceHtml(zoneId, factorId){
  const ids = ((ZONE_SOURCES[zoneId]||{})[factorId]) || [];
  const seen = new Set();
  const items = ids.filter(id=>{ if(seen.has(id)||!SOURCES[id]) return false; seen.add(id); return true; });
  let h = `<div class="fsrc-title ev">Доказательства — источники</div>`;
  if(!items.length){
    return h + `<div class="src-none">Рейтинг этой зоны по этому фактору опирается на общие соображения о лоре и эпохе — точечный источник ещё не подобран (в базе он помечен как «нужен источник»).</div>`;
  }
  h += `<ul class="srclist">`;
  items.forEach(id=>{
    const s = SOURCES[id];
    h += `<li><a href="${s.u}" target="_blank" rel="noopener noreferrer">${s.t}</a> <span class="src-pub">— ${s.p}</span></li>`;
  });
  h += `</ul>`;
  return h;
}

function extraSourcesHtml(zoneId){
  const ids = (ZONE_EXTRA_SOURCES[zoneId]||[]).filter(id=>SOURCES[id]);
  if(!ids.length) return '';
  let h = `<div class="desc-src"><span class="desc-src-label">Проверка по источникам:</span> `;
  h += ids.map(id=>`<a href="${SOURCES[id].u}" target="_blank" rel="noopener noreferrer">${SOURCES[id].p}</a>`).join(', ');
  return h + `</div>`;
}

