function renderList(){
  currentZone = null;
  let h = `
    <div class="fl-title">Зоны — от лучшего совпадения к худшему</div>
    <div class="zone-list">`;
  ZONES.forEach(z=>{
    h += `
      <div class="zrow" data-z="${z.id}">
        <span class="dot" style="background:${TIER_COLOR[z.tier]}"></span>
        <span class="zn">${z.name}</span>
        <span class="zt">${z.tierName}</span>
      </div>`;
  });
  h += `</div>
    <div class="legend-note">
      <span class="frontline-key"></span>пунктир на карте — примерная статичная линия фронта осени 1915 – 1917 гг.; в 1918-м, после Брест-Литовска, немцы двинулись дальше на восток.<br><br>
      Ранжирование <strong>взвешенное</strong>. Два фактора — <span class="lg-key">лось</span> и <span class="lg-key">русскоязычный двор</span> — ключевые: на них держится вся история Анны (гигантский лось убивает её мать; сказки, идиомы и колыбельные матери — русские). Они весят ×3, «немцы прошли через лес» и «многолетний фронт» — ×2, остальное — ×1. Зона, проваливающая оба ключевых фактора, не может быть основным кандидатом, даже если война ложится идеально.<br><br>
      Язык — <strong>про семью, а не про округу</strong>. Единственная фраза канона о языке (Воспоминание №2432: «Кто-то говорит на языке, который она понимает…») сказана о солдатах у фронтовой палатки — а русские солдаты стояли на всём Восточном фронте и зон не различают; о языке окрестных деревень лор молчит вовсе. Зато фольклор Анны — материнский и русский: «Курочка Ряба», «где раки зимуют», «Баюшки-баю». Поэтому фактор проверяет не язык деревень, а другое: мог ли в этом регионе около 1885–1900 гг. реально стоять в лесу изолированный русскоязычный двор — семья на отшибе, вне общины. Такой двор делали возможным староверы, лесная стража казённых лесов и русская колонизация после 1863 г. Это резко усиливает Латгалию и Виленско-Ковенский край (главные староверские ареалы) и обнуляет австрийскую Галицию, где ни один из механизмов не действовал.<br><br>
      Лось оценивается по нужному моменту биографии. Сцена гибели матери — это <strong>детство</strong> Анны (~1885–1895), а не 1915-й; охотится она затем всю жизнь. Европейский лось пережил исторический минимум ареала к началу XX века: на Волыни он был обычен ещё в конце XIX века (детство), но к 1917-му почти исчез. «Звериные» факторы тянут на север, война — на юг; лучше всего они совпадают в Западной Беларуси, где сохранившийся лось, возможный русский двор, многолетний фронт и германский конный рейд сходятся вместе.<br><br>
      Границы зон условны: это не точные полигоны, а области, где сходятся факторы лора.
      Нажмите зону в списке или на карте — откроется разбор по каждому фактору.
      Behaviour Interactive официальных координат не давали; всё здесь — реконструкция по косвенным признакам.
    </div>`;
  panel.innerHTML = h;
  panel.querySelectorAll('.zrow').forEach(el=>{
    el.addEventListener('click',()=>selectZone(el.dataset.z));
  });
}

function selectZone(id){
  const z = ZONES.find(x=>x.id===id);
  if(!z) return;
  currentZone = id;

  map.flyTo(z.center, 7, {duration:.7});
  Object.entries(layers).forEach(([zid,layer])=>{
    layer.setStyle({
      fillOpacity: zid===id ? .40 : .07,
      opacity: zid===id ? 1 : .35
    });
  });

  let h = `
    <button class="back" id="backBtn">← Ко всем зонам</button>
    <div><span class="tier ${z.tier}">${z.tierName}</span></div>
    <h2>${z.name}</h2>
    <div class="modern">${z.modern}</div>
    <div class="desc">${z.desc}</div>
    ${extraSourcesHtml(z.id)}
    <div class="fl-title">Проверка по факторам <span class="fl-sub">— нажмите фактор, чтобы увидеть источник в лоре</span></div>`;
  FACTORS.forEach(f=>{
    const r = z.ratings[f.id];
    h += `
      <div class="frow ${classFor(r)}${f.w>=3?' keyrow':''}" data-f="${f.id}">
        <span class="mark">${markFor(r)}</span>
        <span><span class="fname">${f.name}</span>${f.w>=3?' <span class="fkey">ключевой</span>':''} —
        <span class="fnote">${FNOTES[f.id][r]}</span></span>
        <span class="fw" title="вес фактора при ранжировании">×${f.w}</span>
        <span class="fsrc-toggle">▸</span>
      </div>
      <div class="fsrc" id="fsrc-${f.id}">
        <div class="fsrc-title">Откуда это в лоре</div>
        ${FSOURCES[f.id]}
        ${evidenceHtml(z.id, f.id)}
      </div>`;
  });
  panel.innerHTML = h;
  panel.querySelectorAll('.frow[data-f]').forEach(el=>{
    el.addEventListener('click',()=>{
      const src = document.getElementById('fsrc-'+el.dataset.f);
      const open = src.classList.toggle('open');
      el.querySelector('.fsrc-toggle').textContent = open ? '▾' : '▸';
    });
  });
  document.getElementById('backBtn').addEventListener('click',()=>{
    resetZoneStyles();
    renderList();
    map.flyTo([52.3,27.0], 6, {duration:.7});
  });
  panel.scrollTop = 0;
}

function resetZoneStyles(){
  ZONES.forEach(z=>{
    layers[z.id].setStyle({
      fillOpacity: z.tier==='main' ? .30 : .20,
      opacity:.9
    });
  });
}

renderList();